export function enterNext(event){if(event.key!=='Enter'||event.isComposing||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey)return false;let target=event.target;if(!target||!['INPUT','SELECT'].includes(target.tagName)||['file','submit','button','reset'].includes(target.type))return false;let form=target.closest('form');if(!form)return false;let fields=Array.from(form.querySelectorAll('input,select,textarea')).filter(x=>!x.disabled&&!x.readOnly&&!['hidden','submit','button','reset'].includes(x.type)&&x.getClientRects().length);let i=fields.indexOf(target);if(i<0)return false;event.preventDefault();fields[(i+1)%fields.length]?.focus();return true}
export function bindEnterNavigation(doc){doc.addEventListener('keydown',enterNext)}
